import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Linux and systemd","description":"Install, update and back up ATLAS on Linux.","frontmatter":{"title":"Linux and systemd","description":"Install, update and back up ATLAS on Linux."},"headers":[],"relativePath":"en/projects/atlas/linux.md","filePath":"en/projects/atlas/linux.md","lastUpdated":1792851046000}'),n={name:"en/projects/atlas/linux.md"};function r(l,e,d,o,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="linux-and-systemd" tabindex="-1">Linux and systemd <a class="header-anchor" href="#linux-and-systemd" aria-label="Permalink to &quot;Linux and systemd&quot;">​</a></h1><p>The Linux installer introduced in ATLAS <strong>0.1.298</strong> uses the same combined app server as Docker and the HA app. Administration and Card Editor run together; external plugins remain separately installable. The optional native <a href="/en/projects/atlas/frontend">ATLAS Runtime integration</a> is also implemented and verified through a custom HACS repository on Pi 5 and Proxmox.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Linux with running systemd, Node.js 22 or newer and root access for installation.</li><li>A Linux-built runtime matching the target CPU architecture, libc and Node ABI.</li><li>Three free ports: 4176 for the app, 4175 and 4174 for internal surfaces.</li><li>Space for at least two runtime releases and data backups.</li></ul><p>The builder supports AMD64 and ARM64 and uses Debian Bookworm/glibc. Alpine/musl packages are not interchangeable. Native package preparation is also verified on Raspberry Pi OS / Debian 13.7 Trixie with glibc on a Raspberry Pi 4 (<code>aarch64</code>, 4 GB RAM).</p><p>Qualification as of 2026-10-15: Debian 12 AMD64 LXC and the native Pi 4 with Node.js 22.23.3 and ATLAS 0.1.303/0.1.304. On the Pi, all 17 installer tests, installation, version update, rollback, backup, service restart and automatic recovery after an unhealthy update pass. Synthetic plugin/project data and configuration are preserved. Ports remained loopback-only during that first check. Subsequent qualification passes LAN access on4176, an actual Pi 4 OS reboot, autostart and persistent HA connection recovery from 0.1.305. Further distributions and hardware require separate qualification.</p><p>The installer uses the <code>atlas</code> system account. It refuses an existing account with a different home or primary group and does not silently adopt another ATLAS installation.</p><h2 id="preparing-a-package" tabindex="-1">Preparing a package <a class="header-anchor" href="#preparing-a-package" aria-label="Permalink to &quot;Preparing a package&quot;">​</a></h2><p>On a Linux build host with the existing build dependencies:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux:prepare</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The result is <code>output/linux-runtime</code>: built app, dependencies, reference plugin and <code>atlas-linux-runtime.json</code>. Existing output directories are not overwritten.</p><p>Alternatively, build outside the target LXC with Docker:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packaging/linux/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=local,dest=output/linux-export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The export includes a runtime archive, manifest, checksums and the Node binary with license from the official Node image. Verify provenance and SHA-256 values before use. Use a compatible Node installation; do not blindly replace an existing Node version. Preserve relative <code>node_modules</code> symlinks during transfer and extraction.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>With a verified extracted package and compatible Node version:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/linux-runtime/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/linux-runtime</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atlas</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4176/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The installer validates the package, architecture and native modules, creates a backup, installs a separate release and starts the service. Readiness requires both surfaces, the expected app version and Linux distribution target. Occupied ports are not freed by stopping unrelated services.</p><h2 id="persistent-data" tabindex="-1">Persistent data <a class="header-anchor" href="#persistent-data" aria-label="Permalink to &quot;Persistent data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>/opt/atlas/releases/</code></td><td>Separate runtime releases.</td></tr><tr><td><code>/opt/atlas/current</code></td><td>Symbolic link to the current runtime.</td></tr><tr><td><code>/opt/atlas/installation.json</code></td><td>Installation record and previous release.</td></tr><tr><td><code>/var/lib/atlas/</code></td><td>Persistent data, plugins, identity, file history and trash.</td></tr><tr><td><code>/etc/atlas/atlas.env</code></td><td>Protected configuration, preserved during updates.</td></tr><tr><td><code>/etc/systemd/system/atlas.service</code></td><td>Managed service unit.</td></tr><tr><td><code>/etc/systemd/system/atlas.service.d/</code></td><td>Local systemd overrides.</td></tr><tr><td><code>/var/backups/atlas/</code></td><td>Timestamped backups.</td></tr></tbody></table><p>Editor projects and parts of Administration live in the browser. Export them separately through their respective interfaces. A server backup does not capture browser storage. Keep the same browser address, data location and installation identity across updates so locally bound encrypted credentials remain valid. Docker/HA data is not silently migrated to a new installation.</p><h2 id="update-and-rollback" tabindex="-1">Update and rollback <a class="header-anchor" href="#update-and-rollback" aria-label="Permalink to &quot;Update and rollback&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/new-package/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/new-package</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>ATLAS is stopped and backed up before updating. The environment file, installed plugins and local unit overrides remain intact. The current link switches the runtime. A failed candidate restores the previous runtime. Previously stopped installations remain stopped after validation; existing boot enablement is preserved.</p><p>Rollback changes program files, not user data. Future data migrations need separate backwards-compatibility review. Old releases and backups are not automatically deleted. Use <code>systemctl edit atlas</code> for overrides rather than editing the managed unit directly.</p><h2 id="backup-and-recovery" tabindex="-1">Backup and recovery <a class="header-anchor" href="#backup-and-recovery" aria-label="Permalink to &quot;Backup and recovery&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>A stopped-service backup includes data, configuration, unit, overrides and the installation record. A previously active service restarts afterwards. Backups are root-only and may contain credentials. Back up external paths, SSH keys outside ATLAS data and browser projects separately.</p><p>For manual recovery, stop ATLAS, back up the current state again and restore the selected data/configuration backup at its original paths with appropriate ownership. Preserve the installation identity, provide a matching runtime and check <code>/health</code>. Copying a backup to a different installation does not unlock secrets bound there. A VM/LXC snapshot before first installation also allows recovery of the entire host.</p><h2 id="network-and-plugins" tabindex="-1">Network and plugins <a class="header-anchor" href="#network-and-plugins" aria-label="Permalink to &quot;Network and plugins&quot;">​</a></h2><p>Since ATLAS 0.1.305, saving Linux Administration settings also persists the remembered HA connection server-side using AES-GCM. Restoration after service and host restarts therefore works over LAN HTTP without browser Web Crypto. After updating, enter the existing token once in Administration and save; earlier versions may have retained it only in memory.</p><p>The encrypted <code>admin-connection.enc.json</code> file and private <code>admin-connection.enc.json.key</code> reside beside <code>admin-device.json</code> in the private ATLAS data directory. Files use Linux mode <code>0600</code>; encrypted data is bound to the installation identity. A complete data backup must retain all three files and be treated as confidential. Copying only the runtime directory or browser export does not include this key. “Forget token” also removes the remembered HA token from server-side state. Unreadable encrypted data is not overwritten automatically.</p><p>All surfaces default to loopback; Terminal is disabled. The installer opens no firewall. An administrator may deliberately change <code>ATLAS_APP_HOST</code> for LAN access and restrict that access; internal ports remain local. Administration must not be exposed unprotected to the internet.</p><p>File Studio requires matching Linux file permissions and approved paths. Home Assistant files on another host are not mounted automatically. SSH and Oh My Posh for the external Terminal are optional additional requirements, not included in the Linux package.</p><h2 id="test-scope" tabindex="-1">Test scope <a class="header-anchor" href="#test-scope" aria-label="Permalink to &quot;Test scope&quot;">​</a></h2><p>Installer regressions use disposable data to verify preservation, backup, failed updates, rollback, service state, non-overwriting installation and path/ABI validation. A container test with a simulated service does not replace native systemd testing. Native evidence and open platforms are recorded in <a href="/en/projects/atlas/development-status">Development Status</a>.</p>`,36)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
